node -e '
const fs = require("fs");
const files = fs.readdirSync("specs", {recursive: true}).filter(f => f.endsWith(".md"));
for (const file of files) {
  const content = fs.readFileSync("specs/" + file, "utf8");
  const unlinked = [];
  const lines = content.split("\n");
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line.startsWith("- ") && !line.includes("([validated by")) {
      unlinked.push(`${i+1}: ${line}`);
    }
  }
  if (unlinked.length > 0) {
    console.log(`=== specs/${file} (${unlinked.length} unlinked) ===`);
    for (const u of unlinked.slice(0, 10)) console.log(u);
  }
}
'
